import { createClient } from "@/lib/supabase-server";

export type Project = {
  id: string;
  title: string;
  slug: string;
  location: string | null;
  area: string | null;
  year: number | null;
  description: string | null;
  cover_image: string | null;
  hero_image: string | null;
  sketch_image: string | null;
  position: number;
  featured: boolean;
  published: boolean;
  created_at: string;
  updated_at: string;
};

export type ProjectImage = {
  id: string;
  project_id: string;
  image_url: string;
  caption: string | null;
  position: number;
  created_at: string;
};

export type ProjectWithImages = Project & {
  images: ProjectImage[];
};

export async function getProjects(): Promise<Project[]> {
  const supabase = await createClient();

  const { data, error } = await supabase
    .from("projects")
    .select("*")
    .eq("published", true)
    .order("position", { ascending: true })
    .order("created_at", { ascending: true });

  if (error) {
    console.error("Error cargando proyectos:", error);
    return [];
  }

  return (data ?? []) as Project[];
}

export async function getProjectBySlug(
  slug: string
): Promise<ProjectWithImages | null> {
  const supabase = await createClient();

  const { data: project, error: projectError } = await supabase
    .from("projects")
    .select("*")
    .eq("slug", slug)
    .eq("published", true)
    .maybeSingle();

  if (projectError || !project) {
    if (projectError) {
      console.error(`Error cargando proyecto ${slug}:`, projectError);
    }
    return null;
  }

  const { data: images, error: imagesError } = await supabase
    .from("project_images")
    .select("*")
    .eq("project_id", project.id)
    .order("position", { ascending: true });

  if (imagesError) {
    console.error(`Error cargando imágenes de ${slug}:`, imagesError);
  }

  return {
    ...(project as Project),
    images: (images ?? []) as ProjectImage[],
  };
}

export async function getAdjacentProjects(currentId: string) {
  const projects = await getProjects();

  if (!projects.length) {
    return { previous: null, next: null };
  }

  const currentIndex = projects.findIndex((p) => p.id === currentId);

  if (currentIndex === -1) {
    return { previous: null, next: null };
  }

  const previous =
    currentIndex > 0
      ? projects[currentIndex - 1]
      : projects[projects.length - 1];

  const next =
    currentIndex < projects.length - 1
      ? projects[currentIndex + 1]
      : projects[0];

  return { previous, next };
}
